        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        Busy inodes after unmount..." message and potential crashes when the inode was eventually released.

        Commit message:
        tracing: Fix bad use of igrab in trace_uprobe.c

As Miklos reported and suggested:

  This pattern repeats two times in trace_uprobe.c and in
  kernel/events/core.c as well:

      ret = kern_path(filename, LOOKUP_FOLLOW, &path);
      if (ret)
          goto fail_address_parse;

      inode = igrab(d_inode(path.dentry));
      path_put(&path);

  And it's wrong.  You can only hold a reference to the inode if you
  have an active ref to the superblock as well (which is normally
  through path.mnt) or holding s_umount.

  This way unmounting the containing filesystem while the tracepoint is
  active will give you the "VFS: Busy inodes after unmount..." message
  and a crash when the inode is finally put.

  Solution: store path instead of inode.

This patch fixes two instances in trace_uprobe.c. struct path is added to
struct trace_uprobe to keep the inode and containing mount point
referenced.

Link: http://lkml.kernel.org/r/20180423172135.4050588-1-songliubraving@fb.com

Fixes: f3f096cfedf8 ("tracing: Provide trace events interface for uprobes")
Fixes: 33ea4b24277b ("perf/core: Implement the 'perf_uprobe' PMU")
Cc: stable@vger.kernel.org
Cc: Ingo Molnar <mingo@redhat.com>
Cc: Howard McLauchlan <hmclauchlan@fb.com>
Cc: Josef Bacik <jbacik@fb.com>
Cc: Srikar Dronamraju <srikar@linux.vnet.ibm.com>
Acked-by: Miklos Szeredi <mszeredi@redhat.com>
Reported-by: Miklos Szeredi <miklos@szeredi.hu>
Signed-off-by: Song Liu <songliubraving@fb.com>
Signed-off-by: Steven Rostedt (VMware) <rostedt@goodmis.org>  

        Patch:
         	struct trace_uprobe_filter	filter;
 	struct uprobe_consumer		consumer;
+	struct path			path;
 	struct inode			*inode;
 	char				*filename;

 static void free_trace_uprobe(struct trace_uprobe *tu)
 {
 	int i;

 	for (i = 0; i < tu->tp.nr_args; i++)
 		traceprobe_free_probe_arg(&tu->tp.args[i]);

-	iput(tu->inode);
+	path_put(&tu->path);
 	kfree(tu->tp.call.class->system);
 	kfree(tu->tp.call.name);
 	kfree(tu->filename);
 	kfree(tu);
 }

  */
 static int create_trace_uprobe(int argc, char **argv)
 {
 	struct trace_uprobe *tu;
-	struct inode *inode;
 	char *arg, *event, *group, *filename;
 	char buf[MAX_EVENT_NAME_LEN];
 	struct path path;
 	unsigned long offset;
 	bool is_delete, is_return;
 	int i, ret;

-	inode = NULL;
 	ret = 0;
 	is_delete = false;
 	is_return = false;
 	event = NULL;
 	group = NULL;

 	/* argc must be >= 1 */
 	if (argv[0][0] == '-')
 		is_delete = true;
 	else if (argv[0][0] == 'r')
 		is_return = true;
 	else if (argv[0][0] != 'p') {
 		pr_info("Probe definition must be started with 'p', 'r' or '-'.\n");
 		return -EINVAL;
 	}

 	if (argv[0][1] == ':') {
 		event = &argv[0][2];
 		arg = strchr(event, '/');

 		if (arg) {
 			group = event;
 			event = arg + 1;
 			event[-1] = '\0';

 			if (strlen(group) == 0) {
 				pr_info("Group name is not specified\n");
 				return -EINVAL;
 			}
 		}
 		if (strlen(event) == 0) {
 			pr_info("Event name is not specified\n");
 			return -EINVAL;
 		}
 	}
 	if (!group)
 		group = UPROBE_EVENT_SYSTEM;

 	if (is_delete) {
 		int ret;

 		if (!event) {
 			pr_info("Delete command needs an event name.\n");
 			return -EINVAL;
 		}
 		mutex_lock(&uprobe_lock);
 		tu = find_probe_event(event, group);

 		if (!tu) {
 			mutex_unlock(&uprobe_lock);
 			pr_info("Event %s/%s doesn't exist.\n", group, event);
 			return -ENOENT;
 		}
 		/* delete an event */
 		ret = unregister_trace_uprobe(tu);
 		mutex_unlock(&uprobe_lock);
 		return ret;
 	}

 	if (argc < 2) {
 		pr_info("Probe point is not specified.\n");
 		return -EINVAL;
 	}
 	/* Find the last occurrence, in case the path contains ':' too. */
 	arg = strrchr(argv[1], ':');
-	if (!arg) {
-		ret = -EINVAL;
-		goto fail_address_parse;
-	}
+	if (!arg)
+		return -EINVAL;

 	*arg++ = '\0';
 	filename = argv[1];
 	ret = kern_path(filename, LOOKUP_FOLLOW, &path);
 	if (ret)
-		goto fail_address_parse;
-
-	inode = igrab(d_real_inode(path.dentry));
-	path_put(&path);
+		return ret;

-	if (!inode || !S_ISREG(inode->i_mode)) {
+	if (!d_is_reg(path.dentry)) {
 		ret = -EINVAL;
 		goto fail_address_parse;
 	}

 	ret = kstrtoul(arg, 0, &offset);
 	if (ret)
 		goto fail_address_parse;

 	argc -= 2;
 	argv += 2;

 	/* setup a probe */
 	if (!event) {
 		char *tail;
 		char *ptr;

 		tail = kstrdup(kbasename(filename), GFP_KERNEL);
 		if (!tail) {
 			ret = -ENOMEM;
 			goto fail_address_parse;
 		}

 		ptr = strpbrk(tail, ".-_");
 		if (ptr)
 			*ptr = '\0';

 		snprintf(buf, MAX_EVENT_NAME_LEN, "%c_%s_0x%lx", 'p', tail, offset);
 		event = buf;
 		kfree(tail);
 	}

 	tu = alloc_trace_uprobe(group, event, argc, is_return);
 	if (IS_ERR(tu)) {
 		pr_info("Failed to allocate trace_uprobe.(%d)\n", (int)PTR_ERR(tu));
 		ret = PTR_ERR(tu);
 		goto fail_address_parse;
 	}
 	tu->offset = offset;
-	tu->inode = inode;
+	tu->path = path;
 	tu->filename = kstrdup(filename, GFP_KERNEL);

 	if (!tu->filename) {
 		pr_info("Failed to allocate filename.\n");
 		ret = -ENOMEM;
 		goto error;
 	}

 	/* parse arguments */
 	ret = 0;
 	for (i = 0; i < argc && i < MAX_TRACE_ARGS; i++) {
 		struct probe_arg *parg = &tu->tp.args[i];

 		/* Increment count for freeing args in error case */
 		tu->tp.nr_args++;

 		/* Parse argument name */
 		arg = strchr(argv[i], '=');
 		if (arg) {
 			*arg++ = '\0';
 			parg->name = kstrdup(argv[i], GFP_KERNEL);
 		} else {
 			arg = argv[i];
 			/* If argument name is omitted, set "argN" */
 			snprintf(buf, MAX_EVENT_NAME_LEN, "arg%d", i + 1);
 			parg->name = kstrdup(buf, GFP_KERNEL);
 		}

 		if (!parg->name) {
 			pr_info("Failed to allocate argument[%d] name.\n", i);
 			ret = -ENOMEM;
 			goto error;
 		}

 		if (!is_good_name(parg->name)) {
 			pr_info("Invalid argument[%d] name: %s\n", i, parg->name);
 			ret = -EINVAL;
 			goto error;
 		}

 		if (traceprobe_conflict_field_name(parg->name, tu->tp.args, i)) {
 			pr_info("Argument[%d] name '%s' conflicts with "
 				"another field.\n", i, argv[i]);
 			ret = -EINVAL;
 			goto error;
 		}

 		/* Parse fetch argument */
 		ret = traceprobe_parse_probe_arg(arg, &tu->tp.size, parg,
 						 is_return, false,
 						 uprobes_fetch_type_table);
 		if (ret) {
 			pr_info("Parse error at argument[%d]. (%d)\n", i, ret);
 			goto error;
 		}
 	}

 	ret = register_trace_uprobe(tu);
 	if (ret)
 		goto error;
 	return 0;

 error:
 	free_trace_uprobe(tu);
 	return ret;

 fail_address_parse:
-	iput(inode);
+	path_put(&path);

 	pr_info("Failed to parse address or file.\n");

 	return ret;
 }


 static int
 probe_event_enable(struct trace_uprobe *tu, struct trace_event_file *file,
 		   filter_func_t filter)
 {
 	bool enabled = trace_probe_is_enabled(&tu->tp);
 	struct event_file_link *link = NULL;
 	int ret;

 	if (file) {
 		if (tu->tp.flags & TP_FLAG_PROFILE)
 			return -EINTR;

 		link = kmalloc(sizeof(*link), GFP_KERNEL);
 		if (!link)
 			return -ENOMEM;

 		link->file = file;
 		list_add_tail_rcu(&link->list, &tu->tp.files);

 		tu->tp.flags |= TP_FLAG_TRACE;
 	} else {
 		if (tu->tp.flags & TP_FLAG_TRACE)
 			return -EINTR;

 		tu->tp.flags |= TP_FLAG_PROFILE;
 	}

 	WARN_ON(!uprobe_filter_is_empty(&tu->filter));

 	if (enabled)
 		return 0;

 	ret = uprobe_buffer_enable();
 	if (ret)
 		goto err_flags;

 	tu->consumer.filter = filter;
+	tu->inode = d_real_inode(tu->path.dentry);
 	ret = uprobe_register(tu->inode, tu->offset, &tu->consumer);
 	if (ret)
 		goto err_buffer;

 	return 0;

  err_buffer:
 	uprobe_buffer_disable();

  err_flags:
 	if (file) {
 		list_del(&link->list);
 		kfree(link);
 		tu->tp.flags &= ~TP_FLAG_TRACE;
 	} else {
 		tu->tp.flags &= ~TP_FLAG_PROFILE;
 	}
 	return ret;
 }

 static void
 probe_event_disable(struct trace_uprobe *tu, struct trace_event_file *file)
 {
 	if (!trace_probe_is_enabled(&tu->tp))
 		return;

 	if (file) {
 		struct event_file_link *link;

 		link = find_event_file_link(&tu->tp, file);
 		if (!link)
 			return;

 		list_del_rcu(&link->list);
 		/* synchronize with u{,ret}probe_trace_func */
 		synchronize_sched();
 		kfree(link);

 		if (!list_empty(&tu->tp.files))
 			return;
 	}

 	WARN_ON(!uprobe_filter_is_empty(&tu->filter));

 	uprobe_unregister(tu->inode, tu->offset, &tu->consumer);
+	tu->inode = NULL;
 	tu->tp.flags &= file ? ~TP_FLAG_TRACE : ~TP_FLAG_PROFILE;

 	uprobe_buffer_disable();
 }

 #ifdef CONFIG_PERF_EVENTS
 struct trace_event_call *
 create_local_trace_uprobe(char *name, unsigned long offs, bool is_return)
 {
 	struct trace_uprobe *tu;
-	struct inode *inode;
 	struct path path;
 	int ret;

 	ret = kern_path(name, LOOKUP_FOLLOW, &path);
 	if (ret)
 		return ERR_PTR(ret);

-	inode = igrab(d_inode(path.dentry));
-	path_put(&path);
-
-	if (!inode || !S_ISREG(inode->i_mode)) {
-		iput(inode);
+	if (!d_is_reg(path.dentry)) {
+		path_put(&path);
 		return ERR_PTR(-EINVAL);
 	}

 	/*
 	 * local trace_kprobes are not added to probe_list, so they are never
 	 * searched in find_trace_kprobe(). Therefore, there is no concern of
 	 * duplicated name "DUMMY_EVENT" here.
 	 */
 	tu = alloc_trace_uprobe(UPROBE_EVENT_SYSTEM, "DUMMY_EVENT", 0,
 				is_return);

 	if (IS_ERR(tu)) {
 		pr_info("Failed to allocate trace_uprobe.(%d)\n",
 			(int)PTR_ERR(tu));
+		path_put(&path);
 		return ERR_CAST(tu);
 	}

 	tu->offset = offs;
-	tu->inode = inode;
+	tu->path = path;
 	tu->filename = kstrdup(name, GFP_KERNEL);
 	init_trace_event_call(tu, &tu->tp.call);

 	if (set_print_fmt(&tu->tp, is_ret_probe(tu)) < 0) {
 		ret = -ENOMEM;
 		goto error;
 	}

 	return &tu->tp.call;
 error:
 	free_trace_uprobe(tu);
 	return ERR_PTR(ret);
 }



